commands:
pwsh -NoLogo -NoProfile -Command '
$files = @("./podex.ps1","./api/_lib/pantry-store.ps1","./api/_lib/pantry-render.ps1")
foreach ($f in $files) {
  $errs = $null
  [void][System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $f), [ref]$null, [ref]$errs)
  if ($errs) { Write-Host "PARSE ERRORS in $f"; $errs | ForEach-Object { Write-Host $_.Message } } else { Write-Host "OK $f" }
}
'
